import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { grantAppPrivileges } from './app-role.ts';
import type { Database } from './client.ts';

/** The committed SQL migrations, generated by `pnpm db:generate`. */
export const migrationsFolder = fileURLToPath(new URL('../migrations', import.meta.url));

/**
 * Applies every migration that hasn't run yet, in order, forward-only (ADR-005), then resets
 * the app role's table privileges to the list in `app-role.ts`. The privileges are not in a
 * migration, so they follow the list rather than the migration history, and every place that
 * migrates (the release step, `db:migrate`, the test template) ends with the same grants.
 * Run it from one process at a time (the deploy step), not from app instances.
 */
export async function runMigrations(db: Database): Promise<void> {
  await migrate(db, { migrationsFolder });
  await grantAppPrivileges(db);
}
